import{_ as e,o as a,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Bucket Replication","description":"","frontmatter":{"title":"Ceph Bucket Replication","date":"2026-06-26T00:00:00.000Z","updated":"2026-06-26T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","对象存储","存储集群"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Bucket_Replication.md","filePath":"posts/2026/Ceph_Bucket_Replication.md","lastUpdated":null}'),o={name:"posts/2026/Ceph_Bucket_Replication.md"};function r(s,t,n,c,d,u){return a(),i("div",null,[...t[0]||(t[0]=[l('<h2 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h2><p>本次演讲由 OS Nexus 的 Staff Engineer Seth Kagang 主讲，介绍了 Ceph RGW 的多站点（multi-site）复制功能，重点聚焦于 <strong>Bucket Sync Policies</strong>（桶同步策略）的实际应用，并结合 QuantaStore UI 进行了现场演示。</p><h2 id="一、zone-replication-vs-bucket-replication" tabindex="-1">一、Zone Replication vs Bucket Replication <a class="header-anchor" href="#一、zone-replication-vs-bucket-replication" aria-label="Permalink to &quot;一、Zone Replication vs Bucket Replication&quot;">​</a></h2><p>在配置 Ceph RGW 多站点时，管理员面临两种复制粒度的选择：</p><ul><li><strong>Zone Replication（区域复制）</strong>：更简单的方式，将一个 zone 中的所有数据无差别复制到另一个 zone。</li><li><strong>Bucket Replication（桶复制）</strong>：提供更细粒度的控制，QuantaStore 默认配置为 <strong>default deny rules</strong>（默认拒绝规则），即数据流管道已建立，但实际不会复制任何数据，直到管理员显式指定哪些 bucket 需要同步。</li></ul><p>Bucket 级别复制适用于以下场景：</p><ul><li>带宽受限的站点</li><li>合规性要求数据必须保留在特定区域内</li><li>仅需复制部分 bucket 的场景</li></ul><p>值得注意的是，AWS 支持区域内（intra-zone）桶复制，但当前版本的 Ceph RGW 尚不支持此功能。</p><h2 id="二、bucket-sync-policies-工作机制" tabindex="-1">二、Bucket Sync Policies 工作机制 <a class="header-anchor" href="#二、bucket-sync-policies-工作机制" aria-label="Permalink to &quot;二、Bucket Sync Policies 工作机制&quot;">​</a></h2><p>以一个典型拓扑为例：US East 1 作为主站点（primary），US West 1 和 US West 2 作为二级站点（secondary），三个 zone 被归入同一个 <strong>zone group</strong>。</p><p>关键要点：</p><ul><li>默认情况下，两个 secondary 节点之间<strong>不存在</strong>复制规则，数据仅在 primary 和 secondary 之间流动</li><li>默认 deny rules 仅声明数据流允许通道，实际数据同步需要管理员显式配置 bucket sync policies</li><li>可以为不同 bucket 设置不同的复制目标（例如部分 bucket 复制到 West 1，部分复制到 West 2）</li></ul><h2 id="三、多站点配置注意事项" tabindex="-1">三、多站点配置注意事项 <a class="header-anchor" href="#三、多站点配置注意事项" aria-label="Permalink to &quot;三、多站点配置注意事项&quot;">​</a></h2><p>Ceph RGW <strong>不会</strong>对已存在的数据进行双向合并（bidirectional merge）。因此在配置多站点之前：</p><ol><li><strong>确保两个站点均为空</strong>，以便从干净的状态开始</li><li>配置完成后，系统会进行<strong>完整的 metadata 同步</strong>，包括： <ul><li>所有 S3 用户信息</li><li>Zone group 合并为统一的 group zone</li><li>Primary 站点的 bucket metadata 复制到 secondary</li></ul></li><li>一旦设置了 sync policies，数据将立即开始同步，后续新写入的对象也会自动复制</li></ol><h2 id="四、单向复制与双向复制" tabindex="-1">四、单向复制与双向复制 <a class="header-anchor" href="#四、单向复制与双向复制" aria-label="Permalink to &quot;四、单向复制与双向复制&quot;">​</a></h2><h3 id="unidirectional-单向复制" tabindex="-1">Unidirectional（单向复制） <a class="header-anchor" href="#unidirectional-单向复制" aria-label="Permalink to &quot;Unidirectional（单向复制）&quot;">​</a></h3><ul><li>数据仅从 A 流向 B</li><li>B 站点持有<strong>只读副本</strong></li><li>写入 A 的数据会自动复制到 B，反之则不会</li></ul><h3 id="bidirectional-双向复制" tabindex="-1">Bidirectional（双向复制） <a class="header-anchor" href="#bidirectional-双向复制" aria-label="Permalink to &quot;Bidirectional（双向复制）&quot;">​</a></h3><ul><li>A 和 B 均可写入</li><li>数据最终会达到一致（eventually consistent）</li><li><strong>冲突解决机制</strong>：基于时间戳（timestamp-based），不存在合并概念。当 A 和 B 同时写入时，最新版本将覆盖旧版本，最终保证两个集群的一致性</li></ul><h2 id="五、storage-classes-对复制的影响" tabindex="-1">五、Storage Classes 对复制的影响 <a class="header-anchor" href="#五、storage-classes-对复制的影响" aria-label="Permalink to &quot;五、Storage Classes 对复制的影响&quot;">​</a></h2><p>复制功能<strong>会尊重</strong>不同的存储类别（storage classes）。例如：</p><ul><li>如果 US East 1 配置了 <code>STANDARD</code> 和 <code>STANDARD_IA</code>（低频访问存储），只要 secondary 集群也存在相同的 storage class，复制时会保留对应的存储类别</li><li>若 secondary 集群缺少某个 storage class（如只有 <code>STANDARD</code> 而没有 <code>STANDARD_IA</code>），所有数据将统一归入 <code>STANDARD</code>，原始的 storage class metadata 将丢失</li><li>若数据分层（tiering）功能对业务很重要，需确保两个站点配置相同的 storage classes</li></ul><h2 id="六、现场演示" tabindex="-1">六、现场演示 <a class="header-anchor" href="#六、现场演示" aria-label="Permalink to &quot;六、现场演示&quot;">​</a></h2><p>演讲者通过 QuantaStore UI 和 CLI 进行了现场演示：</p><ol><li><strong>UI 展示</strong>：在 QuantaStore 界面中查看 multi-site 配置、zone group 拓扑、bucket sync policies 的可视化展示</li><li><strong>配置过程</strong>：通过 UI 搜索 bucket → 拖拽至策略配置区 → 选择 <code>enabled</code> → 选择 <code>symmetrical</code>（双向）或 <code>directional</code>（单向）</li><li><strong>CLI 测试</strong>： <ul><li>向双向复制 bucket 的 East 1 写入 5 个对象（每个约 1MB）</li><li>等待约 15 秒后验证 West 1 已同步</li><li>再向 West 1 写入数据，验证 East 1 也已同步</li><li>向单向复制 bucket 的 West 1 写入数据，验证 East 1 <strong>未</strong>收到数据（符合预期）</li></ul></li></ol><h2 id="七、关键要点总结" tabindex="-1">七、关键要点总结 <a class="header-anchor" href="#七、关键要点总结" aria-label="Permalink to &quot;七、关键要点总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>复制粒度</td><td>Zone 级别（全量）或 Bucket 级别（细粒度）</td></tr><tr><td>冲突解决</td><td>基于时间戳，最新版本覆盖旧版本</td></tr><tr><td>Metadata 同步</td><td>配置多站点后自动全量同步</td></tr><tr><td>数据同步</td><td>需显式配置 sync policy 后才开始</td></tr><tr><td>Storage Class</td><td>需两端配置一致才能保留分层信息</td></tr><tr><td>双向复制</td><td>Eventually consistent，不支持合并</td></tr><tr><td>单向复制</td><td>目标端为只读副本</td></tr></tbody></table><h2 id="八、后续建议" tabindex="-1">八、后续建议 <a class="header-anchor" href="#八、后续建议" aria-label="Permalink to &quot;八、后续建议&quot;">​</a></h2><ol><li>生产环境部署前，务必在测试环境验证 sync policy 配置</li><li>多站点配置前确保集群为空，避免 metadata 不一致</li><li>若依赖 storage class 分层，需提前规划两端的 storage class 配置</li><li>双向复制场景下需注意写入冲突的时间戳机制，避免数据覆盖风险</li><li>关注 Ceph RGW 后续版本对 intra-zone bucket replication 的支持进展</li></ol>',30)])])}const g=e(o,[["render",r]]);export{h as __pageData,g as default};
